import FeatureSectionV6 from "./feature-section-v6"

export default function Page() {
  return <FeatureSectionV6 />
}

"use client"

import { MeshGradient } from "@paper-design/shaders-react"

import {
  FSV6_MESH_COLORS,
  FSV6_MESH_SPEED,
  type FeatureShaderTheme,
} from "../lib/features"

type FeatureSectionV6MeshBgProps = FeatureShaderTheme

export function FeatureSectionV6MeshBg({
  swirl,
  rotation,
  distortion,
  scale,
  offsetX,
  offsetY,
  frame,
}: FeatureSectionV6MeshBgProps) {
  return (
    <div className="fsv6-mesh-frame" aria-hidden>
      <MeshGradient
        className="fsv6-mesh-canvas"
        colors={[...FSV6_MESH_COLORS]}
        distortion={distortion}
        fit="cover"
        frame={frame}
        grainMixer={0}
        grainOverlay={0}
        offsetX={offsetX}
        offsetY={offsetY}
        rotation={rotation}
        scale={scale}
        speed={FSV6_MESH_SPEED}
        swirl={swirl}
      />
    </div>
  )
}

.fsv6-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

@media (min-width: 640px) {
  .fsv6-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
  }
}

.fsv6-cell {
  display: flex;
  min-width: 0;
  margin: 0;
}

.fsv6-card {
  position: relative;
  display: flex;
  flex: 1;
  width: 100%;
  min-height: 13.5rem;
  overflow: hidden;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background-color: #0a0a0a;
  color: var(--foreground);
}

.fsv6-mesh-frame {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.fsv6-mesh-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-width: 100%;
  min-height: 100%;
}

.fsv6-mesh-frame canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
}

.fsv6-card-scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(
    165deg,
    color-mix(in oklab, #000000 22%, transparent) 0%,
    color-mix(in oklab, #000000 42%, transparent) 100%
  );
}

.fsv6-card-content {
  position: relative;
  z-index: 10;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  flex: 1;
  padding: 1.35rem 1.4rem 1.4rem;
}

.fsv6-card-title {
  margin: 0;
  font-family: var(--fsv6-body);
  font-size: 1.0625rem;
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.015em;
  word-spacing: -0.06em;
  color: #ffffff;
}

.fsv6-card-desc {
  margin: 0;
  margin-top: auto;
  max-width: 34ch;
  font-family: var(--fsv6-body);
  font-size: 0.8125rem;
  font-weight: 400;
  line-height: 1.6;
  letter-spacing: -0.006em;
  color: color-mix(in oklab, #ffffff 70%, transparent);
}

@media (min-width: 768px) {
  .fsv6-card-content {
    padding: 1.5rem 1.5rem 1.55rem;
  }

  .fsv6-card-title {
    font-size: 1.125rem;
  }

  .fsv6-card-desc {
    font-size: 0.875rem;
    line-height: 1.55;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fsv6-mesh-frame {
    display: none;
  }

  .fsv6-card {
    background-color: color-mix(in oklab, var(--muted) 78%, var(--background) 22%);
  }

  .fsv6-card-scrim {
    display: none;
  }

  .fsv6-card-title {
    color: color-mix(in oklab, var(--foreground) 92%, transparent);
  }

  .fsv6-card-desc {
    color: var(--muted-foreground);
  }
}

/* feature-section v6 — sans typography */

.fsv6-section {
  --fsv6-body: var(--font-sans);
}

.fsv6-intro {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0;
  max-width: 34rem;
}

.fsv6-eyebrow {
  margin: 0 0 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--foreground) 55%, transparent);
}

.fsv6-heading {
  margin: 0 0 0.875rem;
  font-family: var(--fsv6-body);
  font-size: clamp(1.875rem, 3.4vw, 2.5rem);
  font-weight: 500;
  line-height: 1.08;
  letter-spacing: -0.02em;
  word-spacing: -0.08em;
  text-wrap: balance;
}

.fsv6-lead {
  margin: 0;
  max-width: 30rem;
  font-family: var(--fsv6-body);
  font-size: 0.9375rem;
  font-weight: 400;
  line-height: 1.65;
  letter-spacing: -0.01em;
  color: var(--muted-foreground);
}

@media (min-width: 768px) {
  .fsv6-eyebrow {
    margin-bottom: 0.625rem;
    font-size: 0.75rem;
  }

  .fsv6-heading {
    margin-bottom: 1rem;
    font-size: clamp(2rem, 3.6vw, 2.625rem);
  }

  .fsv6-lead {
    font-size: 1rem;
    line-height: 1.7;
  }
}
